import{_ as a,o as e,c as r,a5 as i}from"./chunks/framework.D_J2JZBr.js";const g=JSON.parse('{"title":"一生一芯","description":"理解一生一芯的系统能力训练、当前课程阶段与上科大相关培养项目中的准确适用范围。","frontmatter":{"title":"一生一芯","description":"理解一生一芯的系统能力训练、当前课程阶段与上科大相关培养项目中的准确适用范围。"},"headers":[],"relativePath":"competitions/projects/ysyx.md","filePath":"competitions/projects/ysyx.md","lastUpdated":1795531638000}'),o={name:"competitions/projects/ysyx.md"};function s(h,t,n,d,c,l){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="一生一芯" tabindex="-1">一生一芯 <a class="header-anchor" href="#一生一芯" aria-label="Permalink to &quot;一生一芯&quot;">​</a></h1><p>“一生一芯”（YSYX）是以开源 RISC-V 处理器为切入点的系统能力培养计划：理解程序如何在自己的处理器上运行，也理解 RTL 如何经过实现流程走向芯片。它连接编程、指令集、运行时、处理器、片上系统与物理设计，不是普通的短期比赛，也不是报名后自动获得流片名额。</p><p>官网说明报名与学习免费，不限学校、专业和年级；免费流片的资格、评审和具体安排另有条件，应以官方当期要求为准。零基础可以开始，但需要补课并主动调试，而不是等待手把手教学。</p><h2 id="先选定讲义版本" tabindex="-1">先选定讲义版本 <a class="header-anchor" href="#先选定讲义版本" aria-label="Permalink to &quot;先选定讲义版本&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">新旧阶段名称不同</p><p>截至 2026 年 11 月核实，官方课程主页为 <strong>v26.07</strong>，按 <strong>F → E → D → C → B → A → S</strong> 划分。旧资料中的“预学习 + B/A/S”不能直接套成当前任务清单；官网项目介绍与 FAQ 仍可见旧版用语。报名后先确认适用版本，不混用不同年份的代码框架、指标与答辩规则。</p></div><table tabindex="0"><thead><tr><th>v26.07 阶段</th><th>官方课程主页列出的主要内容</th><th>学习时应关注的闭环</th></tr></thead><tbody><tr><td>F</td><td>科学提问、Logisim、数字逻辑、状态机模型、简单处理器与输入输出</td><td>从状态变化解释电路，而不是只会连线</td></tr><tr><td>E</td><td>HDL、C、Linux、仿真验证、迷你 RISC-V 核、运行时、简易总线与 SoC、后端准备</td><td>最小程序在最小系统上运行；该阶段后有申请入学答辩入口</td></tr><tr><td>D</td><td>C 到二进制、调试器、ISA、AM 运行时、RTL 仿真、基础设施、RV32E NPC</td><td>建立软硬件对应关系与可调试的实现</td></tr><tr><td>C</td><td>ELF 与链接、设备 I/O、调试技巧、总线、SoC</td><td>追踪程序、访存与设备之间的完整链路</td></tr><tr><td>B</td><td>异常处理与简易操作系统、时序、性能优化、简易缓存、流水线</td><td>功能正确后，再分析性能和实现代价</td></tr><tr><td>A</td><td>主页列出乘除法、系统调用、虚存、特权级、xv6、Linux / Debian、缓存和分支预测进阶</td><td>具体讲义与考核按官方后续更新核对</td></tr><tr><td>S</td><td>官网课程主页尚未完整公开具体教学内容</td><td>不根据旧路线自行承诺 S 阶段要求</td></tr></tbody></table><p>这是对公开课程目录的概括，不是官方考核清单。目录中的“流片准备”也不等于已经取得流片资格，不能把完成某个游戏、跑通 Linux 或通过仿真当成通过全部工程与评审要求。</p><h2 id="为什么上科大同学值得关注" tabindex="-1">为什么上科大同学值得关注 <a class="header-anchor" href="#为什么上科大同学值得关注" aria-label="Permalink to &quot;为什么上科大同学值得关注&quot;">​</a></h2><p>它能串起<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115b">数字电路</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cs110">计算机体系结构</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee113">数字集成电路</a>与<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee291f">数字 VLSI 流程</a>中的知识，帮助你发现自己更喜欢架构、RTL、验证、后端，还是系统软件。</p><p><strong>有一条必须精确理解的项目要求：</strong> 信息学院 2026 年 4 月 2 日发布的《上海创芯学院与上海科技大学 2026 年联合招生简介》明确将“一生一芯”列为该联合培养项目的<strong>学位授予硬性门槛</strong>，要求完成架构设计、物理实现、流片制造到硅后验证的完整闭环并通过实测考核。这是该通知描述的联合培养要求，<strong>不能推广为所有上科大本科生或全部研究生的毕业要求</strong>；后续届别以项目正式培养规定为准。参见<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/programs">培养项目</a>。</p><p>公开 YSYX 学习计划与特定学位项目的要求也不是同一个合同：参加公开课程不自动获得该学位项目身份，公开课程的阶段认证也不能自行等同于学位审核通过。</p><h2 id="建议的学习方法" tabindex="-1">建议的学习方法 <a class="header-anchor" href="#建议的学习方法" aria-label="Permalink to &quot;建议的学习方法&quot;">​</a></h2><ol><li><strong>先建立工具基础</strong>：熟悉 Linux、Git、C 与基本数字逻辑。每次环境问题记录原因与解决方法，不反复重装代替排查。</li><li><strong>先建立正确性基线</strong>：理解指令语义与参考模型，使用单元测试、踪迹和差分测试（Differential Testing）定位最早发生的差异。</li><li><strong>再扩展系统</strong>：按适用讲义增加运行时、设备、总线和 SoC。接口、地址映射、复位和时序约定要写清楚。</li><li><strong>最后做性能改进</strong>：测量瓶颈后再加缓存、流水线或预测；修改一个机制就回归验证，不能以一个程序跑通代替正确性。</li><li><strong>保留工程证据</strong>：提交版本、测试范围、失败日志、配置、结果与个人解释都要能追溯。波形与日志优先用于回答具体问题。</li></ol><p>Chisel 并非唯一语言选择。可以根据基础与官方支持选用 Verilog 或 Chisel；在尚未理解逻辑和验证时，同时换语言、换 ISA、换流水线结构会扩大排错范围。不要拿往届完成代码作为自己的实现，也不要让 AI 代写后无法解释。</p><h2 id="时间投入如何估计" tabindex="-1">时间投入如何估计 <a class="header-anchor" href="#时间投入如何估计" aria-label="Permalink to &quot;时间投入如何估计&quot;">​</a></h2><p>不要用“一个暑假一定流片”排计划。官方课程表的小时数是带前提的预估，零基础通常需要更多时间；流片还受资格、评审、资源与批次影响。可先用两周试运行自己的节奏，再决定学期中是否能持续投入；这是规划建议，不是官方周期。</p><p>每周安排完整的开发与调试时段，留下读手册、写记录和回归测试的时间。考试周提前调整并按项目规则请假。阶段结束时用一页说明回答“实现了什么、如何验证、仍有哪些问题、下一步是什么”，不要只统计代码行数或在线时长。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>分享一生一芯学习方法，注明讲义版本与阶段，只公开自己有权公开的技术记录，不上传他人解答、个人账号或内部考核材料。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://ysyx.oscc.cc/" target="_blank" rel="noreferrer">一生一芯官网</a></li><li><a href="https://ysyx.oscc.cc/docs/" target="_blank" rel="noreferrer">官方课程主页：当前 v26.07</a></li><li><a href="https://ysyx.oscc.cc/project/intro.html" target="_blank" rel="noreferrer">官方项目概述</a>与<a href="https://ysyx.oscc.cc/project/faq.html" target="_blank" rel="noreferrer">FAQ</a>：部分表述保留旧版本阶段名称，当前学习以对应讲义为准。</li><li><a href="https://sist.shanghaitech.edu.cn/2026/0402/c2858a1120477/page.htm" target="_blank" rel="noreferrer">上海创芯学院与上科大 2026 年联合招生简介</a></li></ul>',20)])])}const u=a(o,[["render",s]]);export{g as __pageData,u as default};
